The pseudocode below implements the exponential mechanism. Does this implementation ensure $\varepsilon$-differential privacy under the add/remove neighboring relationship?

\BlankLine

\begin{algorithm}[H]
\caption{Exponential Mechanism}
\DontPrintSemicolon
\SetNoFillComment
\SetKwInOut{Input}{Input}
\SetKwInOut{Output}{Output}

\Input{
Dataset $D = \{z_i\}_{i=1}^n$;\,
candidate set $Y$;\,
utility (score) function $q(D, y)=\sum_{i=1}^n \mathbf{1}\{z_i=y\}$;\,
privacy parameter $\varepsilon$
}

\Output{
Selected item $\hat{y} \in Y$ sampled by the exponential mechanism
}

\BlankLine
\For{$y \in Y$}{
    $p_y \leftarrow 
    \frac{\exp\left(\varepsilon\, q(D, y)\right)}
         {\sum_{y' \in Y} \exp\left(\varepsilon\, q(D, y')\right)}$
}

Sample $\hat{y} \sim \mathrm{Multinomial}(1; \{p_y\}_{y \in Y})$\;
\Return{$\hat{y}$}
\end{algorithm}

