The following is an implementation of differentially private gradient descent (DP-GD). Does this implementation satisfy $\mu$-Gaussian differential privacy under the add/remove neighboring relationship (assume number of samples $n$ is public information)?

\begin{algorithm}[H]
\caption{DP-GD with Gaussian Noise }
\DontPrintSemicolon
\SetNoFillComment
\SetKwInOut{Input}{Input}\SetKwInOut{Output}{Output}
\Input{
Dataset $D=\{z_i\}_{i=1}^n$;\,
loss $\ell(\theta;z)$;\,
initial parameter $\theta_0\in\mathbb{R}^d$;\,
iterations $T$;\,
step sizes $\{\eta_t\}_{t=0}^{T-1}$;\,
clipping norm $C>0$;\,
target gaussian DP $\mu$
}
\Output{Final parameter $\theta_T$  }
\BlankLine
\textbf{Setting noise distribution:} $\xi_0$ is sampled from $\mathcal{N}(0, I_d)$, as used in the noise multiplier for gaussian mechanism; \,

\For{$t=0,\dots,T-1$}{
  $\xi_t \sim \mathcal{N}(0, I_d)$\;
  \For{$i=1,\dots,n$}{
    $g_i \leftarrow \nabla_\theta \ell(\theta_t; z_i)$\;
    $\hat g_i \leftarrow  g_i \cdot \min\!\bigl(1,\, \tfrac{C}{\|g_i\|_2}\bigr)$\;
  }
  \uIf{$t\mod{2}==0$}{$\xi=\xi_{\lfloor t/2 \rfloor}$}
  \Else{$\xi=\xi_t$}
  $\tilde g_t \leftarrow \frac{1}{n}\left(\sum_{i=1}^n \hat g_i + \frac{C\sqrt{T}}{\mu}\xi \right)$\; 
  $\theta_{t+1} \leftarrow \theta_t \;-\; \eta_t \,\tilde g_t$\;
}

\Return{$\theta_T$}
\end{algorithm}

The following is an implementation of differentially private gradient descent (DP-GD). Does this implementation satisfy $\mu$-Gaussian differential privacy under the add/remove neighboring relationship?

\begin{algorithm}[H]
\caption{DP-GD with Gaussian Noise }

\DontPrintSemicolon
\SetNoFillComment
\SetKwInOut{Input}{Input}\SetKwInOut{Output}{Output}
\Input{
Dataset $D=\{z_i\}_{i=1}^n$;\,
loss $\ell(\theta;z)$;\,
initial parameter $\theta_0\in\mathbb{R}^d$;\,
iterations $T$;\,
step sizes $\{\eta_t\}_{t=0}^{T-1}$;\,
clipping norm $C>0$;\,
data batches $\mathcal{B}=\{B_1,...,B_k\}$, i.e. a partition of $D$;\,
target gaussian DP $\mu$
}
\Output{Final parameter $\theta_T$  }
\BlankLine

\For{$t=0,\dots,T-1$}{
  \For{$i=1,\dots,k$}{
    $g_i = \frac{1}{|B_i|}\sum_{k \in B_i}\nabla_{\theta}\ell(\theta_t;z_i)$\;
    $\tilde g_i = g_i + \frac{C\sqrt{T}}{\mu}\xi_i, \quad \xi_i \sim \mathcal{N}(0, I_d)$\;
    $\tilde g_i \leftarrow  \tilde g_i \cdot \min\!\bigl(1,\, \tfrac{C}{\|\tilde g_i\|_2}\bigr)$\;
  }
  $\theta_{t+1} \leftarrow \theta_t \;-\; \eta_t \sum_{i=1}^{k}\tilde g_i$\;
}

\Return{$\theta_T$}
\end{algorithm}

The following is an implementation of differentially private gradient descent (DP-GD). Does this implementation satisfy $\mu$-Gaussian differential privacy under the add/remove neighboring relationship (assume number of samples $n$ is public information)?

\begin{algorithm}[H]
\caption{DP-GD with Gaussian Noise }

\DontPrintSemicolon
\SetNoFillComment
\SetKwInOut{Input}{Input}\SetKwInOut{Output}{Output}
