Is the following algorithm $(\varepsilon, \delta)$-differentially private?


\begin{algorithm}[H]
\caption{Outputting a private Johnson--Lindenstrauss projection of a matrix.}
\KwIn{A matrix $A \in \mathbb{R}^{n \times d}$ and a bound $B > 0$ on the $\ell_2$-norm of any row in $A$; Privacy parameters: $\varepsilon, \delta > 0$; Parameter $r$ indicating the number of rows in the resulting matrix.}

\BlankLine
Set $w$ such that 
\[
w^2 = \frac{8B^2}{\varepsilon} \left( \sqrt{2r \ln(8/\delta)} + 2\ln(8/\delta) \right).
\]
Sample $Z \sim \mathrm{Lap}(4B^2 / \varepsilon)$ and let $\sigma_{\min}(A)$ denote the smallest singular value of $A$.

\BlankLine
\If{$\sigma_{\min}(A)^2 > w^2 + Z + \frac{4B^2 \ln(1/\delta)}{\varepsilon}$}{
    Sample a $(r \times n)$-matrix $R$ whose entries are i.i.d.\ samples from a normal Gaussian.\;
    \Return{$RA$ and ``matrix unaltered''}\;
}
\Else{
    Let $A'$ denote the result of appending $A$ with the $d \times d$-matrix $wI_{d \times d}$.\;
    Sample a $(r \times (n + d))$-matrix $R$ whose entries are i.i.d.\ samples from a normal Gaussian.\;
    \Return{$RA'$ and ``matrix altered''}\;
}
\end{algorithm}

