Given a privacy accountant $\mathcal{O}$ such that, given target privacy parameters $(\varepsilon,\delta)$, the Poisson subsampling rate $q$, and the number of DP-SGD iterations $T$ (i.e., the number of compositions), returns the calibrated noise multiplier $\sigma$ for the subsampled Gaussian mechanism used in DP-SGD under the add/remove neighbouring relation. Can the following implementation of DP-SGD satisfy $(\varepsilon,\delta)$-DP for some $\varepsilon>0$ and $\delta\in(0,1)$, under the add/remove neighbouring relation?

\begin{algorithm}[H]
\caption{DP-SGD}
\DontPrintSemicolon
\SetKwInput{KwIn}{Input}
\KwIn{loss function $\mathcal{L}(\theta)=\frac{1}{N}\sum_{x \in D}\mathcal{L}(\theta,x)$, iterations $T$, dataset $D=\{x_1,\ldots,x_N\}$, sampling rate $q$, clipping bound $C$, learning rate $\eta$, initial weights $\theta_0$}
\textbf{Set:} $\sigma\leftarrow\mathcal{O}(\varepsilon,\delta,q,T)$ \\
\For{$t=0, \ldots, T-1$}{
  $B \sim \text{PoissonSample}(D, q)$ \\
  \For{$x_i \in B$}{
    $g_i \leftarrow \nabla_{\theta_t} \mathcal{L}(\theta_t, x_i)$ 

    $g_i^{\text{clip}} \leftarrow g_i \cdot \min\!\left(1, \frac{C}{\lVert g_i\rVert_2}\right)$ 
  }

  $\bar g \leftarrow \frac{1}{q}\!\left(\sum_{i\in B} g_i^{\text{clip}} + \mathcal{N}(0, \sigma^2 C^2 I_d)\right)$ 

  $\theta_{t+1} \leftarrow \theta_t - \eta \bar g$ 
}
\KwRet{$\theta_T$}
\end{algorithm}

