\begin{algorithm}[H]
\caption{Trimmed Mean estimation}
\SetKwInOut{Input}{Input}
\SetKwInOut{Output}{Output}
\Input{Input scalar dataset $D:=\{x_1,\ldots,x_n\} \in [0,1]^n$, integer $m \in [0,n/2)$}
